 34	    uint256 currentTime = block.timestamp;
 35	    if (params.endTime <= currentTime) revert InvalidEndTime(currentTime, params.endTime);
 36	    uint256 saleDuration = uint256(params.endTime) - currentTime;
 37	    if (saleDuration > RaffleConstants.MAX_SALE_DURATION) {
 38	        revert SaleDurationTooLong(saleDuration, RaffleConstants.MAX_SALE_DURATION);
 39	    }
