 42	```
 43	
 44	- The only implemented creation entrypoint passes that immutable address to the ordinary `Clones.clone` overload (`RaffleFactory.sol:L97-L106`). Sponsor-controlled creation parameters cannot select the target.
 45	
 46	```solidity
 47	// target/packages/contracts/node_modules/@openzeppelin/contracts/proxy/Clones.sol:L32-L62
 48	function clone(address implementation) internal returns (address instance) {
 49	    return clone(implementation, 0);
 50	}
 51	
 52	function clone(address implementation, uint256 value) internal returns (address instance) {
 53	    if (address(this).balance < value) {
 54	        revert Errors.InsufficientBalance(address(this).balance, value);
 55	    }
 56	    assembly ("memory-safe") {
 57	        mstore(0x00, or(shr(232, shl(96, implementation)), 0x3d602d80600a3d3981f3363d3d373d3d3d363d73000000))
 58	        mstore(0x20, or(shl(120, implementation), 0x5af43d82803e903d91602b57fd5bf3))
